    'or-IN': 'ଡାକ୍ତରଖାନାରେ ଭର୍ତ୍ତି ହେବା ପୂର୍ବର ଖର୍ଚ୍ଚ, ପରୀକ୍ଷା ନିରୀକ୍ଷା, ଅସ୍ତ୍ରୋପଚାର (ସର୍ଜରୀ), ଆଇସିୟୁ, ଔଷଧ ଏବଂ ୧୫ ଦିନର ପରବର୍ତ୍ତୀ ଯତ୍ନ ଅନ୍ତର୍ଭୁକ୍ତ।',
