    'mr-IN': 'वर्षभर सक्रिय. पात्र नागरिक कोणत्याही अंतिम तारखेशिवाय अधिकृत पोर्टलवर किंवा जवळच्या सीएससी केंद्रावर कधीही अर्ज सादर करू शकतात.',
