    'kn-IN': 'ವರ್ಷಪೂರ್ತಿ ಸಕ್ರಿಯವಾಗಿದೆ. ಅರ್ಹ ನಾಗರಿಕರು ಯಾವುದೇ ಕೊನೆಯ ದಿನಾಂಕವಿಲ್ಲದೆ ಅಧಿಕೃತ ಪೋರ್ಟಲ್ ಅಥವಾ ಹತ್ತಿರದ ಸಿಎಸ್‌ಸಿ ಕೇಂದ್ರದಲ್ಲಿ ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು.',
    'ml-IN': 'വർഷം മുഴുവൻ സജീവം. അർഹരായ പൗരന്മാർക്ക് അവസാന തീയതി ഇല്ലാതെ ഔദ്യോഗിക പോർട്ടലിലോ അടുത്തുള്ള സി‌എസ്‌സി കേന്ദ്രത്തിലോ എപ്പോൾ വേണമെങ്കിലും അപേക്ഷ സമർപ്പിക്കാം.',
    'pa-IN': 'ਸਾਰਾ ਸਾਲ ਸਰਗਰਮ। ਯੋਗ ਨਾਗਰਿਕ ਬਿਨਾਂ ਕਿਸੇ ਆਖਰੀ ਮਿਤੀ ਦੇ ਅਧਿਕਾਰਤ ਪੋਰਟਲ ਜਾਂ ਨਜ਼ਦੀਕੀ ਸੀਐਸਸੀ ਕੇਂਦਰ \'ਤੇ ਕਿਸੇ ਵੀ ਸਮੇਂ ਅਰਜ਼ੀ ਜਮ੍ਹਾਂ ਕਰ ਸਕਦੇ ਹਨ।',
