    'ml-IN': 'രജിസ്റ്റർ ചെയ്ത മൊബൈൽ അല്ലെങ്കിൽ ആധാർ ഉപയോഗിച്ച് പേയ്‌മെന്റ് സ്റ്റാറ്റസ് ഓൺലൈനിൽ പരിശോധിക്കുക.',
