    'gu-IN': 'OTP અથવા CSC બાયોમેટ્રિક ઉપકરણનો ઉપયોગ કરીને પોર્ટલ પર ઈ-કેવાયસી પૂર્ણ કરો.',
    'kn-IN': 'OTP ಅಥವಾ CSC ಬಯೋಮೆಟ್ರಿಕ್ ಸಾಧನವನ್ನು ಬಳಸಿಕೊಂಡು ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಇ-ಕೆವೈಸಿ ಪೂರ್ಣಗೊಳಿಸಿ.',
    'ml-IN': 'OTP അല്ലെങ്കിൽ CSC ബയോമെട്രിക് ഉപകരണം ഉപയോഗിച്ച് പോർട്ടലിൽ ഇ-കെവൈസി പൂർത്തിയാക്കുക.',
