    'pa-IN': 'OTP ਜਾਂ CSC ਬਾਇਓਮੈਟ੍ਰਿਕ ਡਿਵਾਈਸ ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਪੋਰਟਲ \'ਤੇ ਈ-ਕੇਵਾਈਸੀ ਪੂਰਾ ਕਰੋ।',
    'ur-IN': 'او ٹی پی یا سی ایس سی بائیو میٹرک ڈیوائس کا استعمال کرتے ہوئے پورٹل پر ای کے وائی سی مکمل کریں۔',
