    'gu-IN': 'KVIC ઈ-લર્નિંગ પોર્ટલ દ્વારા EDP તાલીમ 100% ઓનલાઇન પૂર્ણ કરી શકાય છે.',
    'kn-IN': 'KVIC ಇ-ಲರ್ನಿಂಗ್ ಪೋರ್ಟಲ್ ಮೂಲಕ EDP ತರಬೇತಿಯನ್ನು 100% ಆನ್‌ಲೈನ್‌ನಲ್ಲಿ ಪೂರ್ಣಗೊಳಿಸಬಹುದು.',
