    'pa-IN': 'KVIC ਈ-ਲਰਨਿੰਗ ਪੋਰਟਲ ਰਾਹੀਂ EDP ਸਿਖਲਾਈ 100% ਆਨਲਾਈਨ ਪੂਰੀ ਕੀਤੀ ਜਾ ਸਕਦੀ ਹੈ।',
