    'kn-IN': 'ನಿಮ್ಮ ಬ್ಯಾಂಕ್ ಖಾತೆ ಸಕ್ರಿಯವಾಗಿದೆ ಮತ್ತು NPCI ಮ್ಯಾಪರ್‌ನಲ್ಲಿ ಆಧಾರ್‌ನೊಂದಿಗೆ ಲಿಂಕ್ ಆಗಿದೆ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.',
