    'pa-IN': 'ਯਕੀਨੀ ਬਣਾਓ ਕਿ ਤੁਹਾਡਾ ਬੈਂਕ ਖਾਤਾ ਕਿਰਿਆਸ਼ੀਲ ਹੈ ਅਤੇ NPCI ਮੈਪਰ \'ਤੇ ਆਧਾਰ ਨਾਲ ਲਿੰਕ ਹੈ।',
    'ur-IN': 'یقینی بنائیں کہ آپ کا بینک اکاؤنٹ فعال ہے اور این پی سی آئی میپر پر آدھار سے منسلک ہے۔',
