    'ml-IN': 'മികച്ച ജോലി സാധ്യതകൾക്കായി "പ്ലേസ്‌മെന്റ് ലിങ്ക്ഡ്" കോഴ്സുകൾ തിരഞ്ഞെടുക്കുക.',
