    'pa-IN': 'ਵਧੀਆ ਨੌਕਰੀਆਂ ਲਈ "ਪਲੇਸਮੈਂਟ ਲਿੰਕਡ" ਅਨੁਸਾਰ ਕੋਰਸਾਂ ਨੂੰ ਫਿਲਟਰ ਕਰੋ।',
    'ur-IN': 'زیادہ سے زیادہ ملازمت کے مواقع کے لیے "پلیسمنٹ سے منسلک" کورسز منتخب کریں۔',
