    'or-IN': 'ଆପଣଙ୍କ ପ୍ରଶାସନିକ କାର୍ଯ୍ୟାଳୟରୁ କଲେଜର AISHE / UDISE କୋଡ୍ ପ୍ରସ୍ତୁତ ରଖନ୍ତୁ।',
    'pa-IN': 'ਆਪਣੇ ਪ੍ਰਸ਼ਾਸਕੀ ਦਫ਼ਤਰ ਤੋਂ ਕਾਲਜ ਦਾ AISHE / UDISE ਕੋਡ ਤਿਆਰ ਰੱਖੋ।',
