    'or-IN': 'ଆପଣଙ୍କ ନାମ ଯାଞ୍ଚ କରିବା ପାଇଁ ଗ୍ରାମ ରୋଜଗାର ସେବକ କିମ୍ବା ପଞ୍ଚାୟତ ସଚିବଙ୍କୁ ଭେଟନ୍ତୁ।',
