const MONTH_ALIASES: Record<string, string> = {
  'jan': 'january', 'feb': 'february', 'mar': 'march', 'apr': 'april',
  'may': 'may', 'jun': 'june', 'jul': 'july', 'aug': 'august',
  'sep': 'september', 'sept': 'september', 'oct': 'october', 'nov': 'november', 'dec': 'december',
};

/**
 * Localizes dates containing English month names into the requested Indic language
 * e.g., "20 February 2025" -> "20 ଫେବୃଆରୀ 2025" (Odia)
 */
export const translateDateString = (dateStr: string, langCode: string): string => {
  if (!dateStr || !langCode || langCode === 'en-IN' || langCode === 'en') return String(dateStr || '');
  if (typeof dateStr !== 'string') {
    try {
      dateStr = String(dateStr || '');
    } catch {
      return '';
    }
  }
  if (!dateStr) return '';

  const monthRegex = /\b(January|February|March|April|May|June|July|August|September|October|November|December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)\b/gi;
  return dateStr.replace(monthRegex, (match) => {
    const lower = match.toLowerCase();
    const canonical = MONTH_ALIASES[lower] || lower;
    return INDIC_MONTHS[canonical]?.[langCode] || match;
  });
};

// Fast cache for case-insensitive lookup
let lowerCaseMap: Map<string, Record<string, string>> | null = null;

function getLowerCaseGlossary(): Map<string, Record<string, string>> {
  if (!lowerCaseMap) {
    lowerCaseMap = new Map();
    for (const [key, value] of Object.entries(PHRASE_GLOSSARY)) {
      lowerCaseMap.set(key.trim().toLowerCase(), value);
    }
  }
  return lowerCaseMap;
}

/**
 * Translates any phrase using the glossary with case-insensitive, step-prefix, and date support
 */
export const translateGlossaryPhrase = (phrase: string, langCode: string): string => {
  if (!phrase || !langCode || langCode === 'en-IN' || langCode === 'en') return String(phrase || '');
  if (typeof phrase !== 'string') {
    try {
      phrase = String(phrase || '');
    } catch {
      return '';
    }
  }
  if (!phrase) return '';
  const trimmed = phrase.trim();
  if (!trimmed) return '';

  // 1. Direct exact match
  if (PHRASE_GLOSSARY[trimmed] && PHRASE_GLOSSARY[trimmed][langCode]) {
    return PHRASE_GLOSSARY[trimmed][langCode];
  }

  // 2. Case-insensitive match (e.g. "IDENTITY", "OTHER", "INSURANCE", "HEALTHCARE")
  const lowerMap = getLowerCaseGlossary();
  const lowerEntry = lowerMap.get(trimmed.toLowerCase());
  if (lowerEntry && lowerEntry[langCode]) {
    return lowerEntry[langCode];
  }

  // 3. Fallback without trailing colon or period if present
  const stripped = trimmed.replace(/[:.]+$/, '').trim();
  if (stripped !== trimmed) {
    if (PHRASE_GLOSSARY[stripped] && PHRASE_GLOSSARY[stripped][langCode]) {
      return PHRASE_GLOSSARY[stripped][langCode];
    }
    const strippedLowerEntry = lowerMap.get(stripped.toLowerCase());
    if (strippedLowerEntry && strippedLowerEntry[langCode]) {
      return strippedLowerEntry[langCode];
    }
  }

  // 4. Step prefix translation: "Step 01", "Step 1", "Step-02", "Step 1."
  const stepMatch = trimmed.match(/^Step[-\s]*0*(\d+)(.*)$/i);
  if (stepMatch) {
    const num = stepMatch[1];
    const rest = stepMatch[2].trim();
    const STEP_WORDS: Record<string, string> = {
      'hi-IN': 'चरण', 'bn-IN': 'ধাপ', 'te-IN': 'దశ', 'ta-IN': 'படி',
      'mr-IN': 'टप्पा', 'gu-IN': 'પગલું', 'kn-IN': 'ಹಂತ', 'ml-IN': 'ഘട്ടം',
      'or-IN': 'ପଦକ୍ଷେପ', 'pa-IN': 'ਕਦਮ', 'ur-IN': 'مرحلہ'
    };
    const stepWord = STEP_WORDS[langCode] || 'Step';
    if (!rest) {
      return `${stepWord} ${num}`;
    }
    const cleanRest = rest.replace(/^[:.\-\s]+/, '');
    if (!cleanRest) {
      return `${stepWord} ${num}`;
    }
    return `${stepWord} ${num}: ${translateGlossaryPhrase(cleanRest, langCode)}`;
  }

  // 5. Date localization (e.g. "20 February 2025" or "10 Jan 2024")
  const dateLocalized = translateDateString(trimmed, langCode);
  if (dateLocalized !== trimmed) {
    return dateLocalized;
  }

  // 6. Gemini dynamic cache
  const geminiCached = getCachedTranslation(trimmed, langCode);
  if (geminiCached) {
    return geminiCached;
  }

  // 7. Background Gemini translation for unknown English words
  if (typeof window !== 'undefined' && /[a-zA-Z]{3,}/.test(trimmed)) {
    translateWithGemini(trimmed, langCode).catch(() => {});
  }

  return phrase;
};
